def json_path_get(obj, path: str, default=None):
    if not isinstance(path, str):
        return default
    if path == '':
        return obj

    keyed_re = re.compile(r'[^.\[\]]+(?:\[\d+\])*')
    bare_re = re.compile(r'(?:\[\d+\])+')

    pieces = []
    for segment in path.split('.'):
        if keyed_re.fullmatch(segment):
            key = re.match(r'[^.\[\]]+', segment).group(0)
            indices = [int(x) for x in re.findall(r'\[(\d+)\]', segment[len(key):])]
            pieces.append((key, indices))
        elif bare_re.fullmatch(segment):
            indices = [int(x) for x in re.findall(r'\[(\d+)\]', segment)]
            pieces.append((None, indices))
        else:
            return default

    cur = obj
    for key, indices in pieces:
        if key is not None:
            if not isinstance(cur, dict):
                return default
            if key not in cur:
                return default
            cur = cur[key]
        for idx in indices:
            if not isinstance(cur, list):
                return default
            if idx >= len(cur):
                return default
            cur = cur[idx]
    return cur
