import re
from typing import Any

_NAME_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")


def _parse_path(path):
    if path.startswith(".") or path.endswith(".") or ".." in path:
        raise ValueError("invalid path")
    steps = []
    i = 0
    n = len(path)
    while i < n:
        ch = path[i]
        if ch == ".":
            i += 1
            continue
        if ch == "[":
            j = path.find("]", i + 1)
            if j == -1:
                raise ValueError("unterminated index")
            inner = path[i + 1:j]
            if re.fullmatch(r"[0-9]+", inner) is None:
                raise ValueError("invalid index")
            steps.append(("i", int(inner)))
            i = j + 1
        else:
            m = _NAME_RE.match(path, i)
            if m is None:
                raise ValueError("invalid segment")
            steps.append(("k", m.group(0)))
            i = m.end()
        if i < n and path[i] not in ".[":
            raise ValueError("invalid character after segment")
    return steps


def json_path_get(obj: Any, path: str, default: Any = None) -> Any:
    if path is None:
        return default
    if not isinstance(path, str):
        return default
    if path.strip() == "":
        return obj
    try:
        steps = _parse_path(path)
    except ValueError:
        return default
    cur = obj
    for kind, val in steps:
        if kind == "k":
            if isinstance(cur, dict) and val in cur:
                cur = cur[val]
            else:
                return default
        else:
            if isinstance(cur, list) and 0 <= val < len(cur):
                cur = cur[val]
            else:
                return default
    return cur
